#!/bin/bash
set -euo pipefail
cd "$(dirname "$0")/.."
# The independent all-pose source images are generated by test-sonic-animation.
test -s build/sonic-animation/expected-frames.bin
python3 tools/sonic_frame_assets.py
# sonic_view.inc calls the real water raster CLUT hook (water_raster.h);
# src/water_raster.c links against the host <yaul.h> stand-in in tools/host_yaul.
clang -std=c11 -O1 -g -Wall -Wextra -Werror -Isrc -Itools/host_yaul -include water_raster.h \
    -fsanitize=address,undefined -fno-sanitize-recover=all \
    tools/sonic_view_test.c src/sonic_frames.c src/water_raster.c -o build/sonic-view-test
build/sonic-view-test
